    monkeypatch, hostname, allowed_hosts, registered
):
    if hostname is None:
        monkeypatch.delenv("HOSTNAME", raising=False)
    else:
        monkeypatch.setenv("HOSTNAME", hostname)

    scheduler = OlAsyncIOScheduler()

    @limit_server(allowed_hosts, scheduler)
